/**
 * ALOOKHOR AKX Header — mobile drawer + search toggle.
 * Works with the dynamic IDs generated by PHP per shortcode instance.
 */
(function () {
  'use strict';

  function initRoot(root) {
    if (!root || root.dataset.akxReady === '1') return;
    root.dataset.akxReady = '1';

    const menuButton = root.querySelector('.akx-menu-button');
    const drawer = root.querySelector('.akx-mob-drawer');
    const backdrop = root.querySelector('.akx-mob-backdrop');
    const closeBtns = root.querySelectorAll('.akx-mob-close, .akx-mob-backdrop');
    const searchButton = root.querySelector('.akx-search-button');
    const searchPanel = root.querySelector('.akx-search-panel');

    let drawerReturnFocus = null;
    function openDrawer() {
      drawerReturnFocus = document.activeElement;
      if (drawer) { drawer.classList.add('is-open'); drawer.setAttribute('aria-hidden','false'); }
      if (backdrop) { backdrop.classList.add('is-open'); backdrop.setAttribute('aria-hidden','false'); }
      if (menuButton) menuButton.setAttribute('aria-expanded','true');
      document.documentElement.classList.add('akx-mobile-menu-open');
      document.body.classList.add('akx-mobile-menu-open');
      requestAnimationFrame(() => drawer?.querySelector('.akx-mob-close, a, button, input')?.focus());
    }
    function closeDrawer(restoreFocus = true) {
      if (drawer) { drawer.classList.remove('is-open'); drawer.setAttribute('aria-hidden','true'); }
      if (backdrop) { backdrop.classList.remove('is-open'); backdrop.setAttribute('aria-hidden','true'); }
      if (menuButton) menuButton.setAttribute('aria-expanded','false');
      document.documentElement.classList.remove('akx-mobile-menu-open');
      document.body.classList.remove('akx-mobile-menu-open');
      if (restoreFocus && drawerReturnFocus instanceof HTMLElement) drawerReturnFocus.focus();
    }

    if (menuButton && drawer) menuButton.addEventListener('click', openDrawer);
    if (closeBtns) {
      closeBtns.forEach(function (el) {
        if (el !== backdrop) el.addEventListener('click', closeDrawer);
      });
    }
    if (backdrop) backdrop.addEventListener('click', () => closeDrawer());
    if (drawer) drawer.addEventListener('keydown', function (event) {
      if (event.key === 'Escape') { event.preventDefault(); closeDrawer(); return; }
      if (event.key !== 'Tab') return;
      const focusable = [...drawer.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(el => el.offsetParent !== null);
      if (!focusable.length) { event.preventDefault(); drawer.focus(); return; }
      const first = focusable[0], last = focusable[focusable.length - 1];
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    });

    // Mobile submenu accordion
    var toggles = root.querySelectorAll('.akx-mob-toggle');
    toggles.forEach(function (t) {
      t.addEventListener('click', function (e) {
        e.preventDefault();
        const open = t.parentElement.classList.toggle('is-open');
        t.setAttribute('aria-expanded', open ? 'true' : 'false');
      });
    });

    // Desktop search panel
    if (searchButton && searchPanel) {
      searchButton.addEventListener('click', function (e) {
        e.stopPropagation();
        searchPanel.classList.toggle('is-open');
        if (searchPanel.classList.contains('is-open')) {
          var input = searchPanel.querySelector('input');
          if (input) input.focus();
        }
      });
    }

    // Outside click closes drawer + search
    document.addEventListener('click', function (e) {
      if (!root.contains(e.target)) {
        closeDrawer();
        if (searchPanel) searchPanel.classList.remove('is-open');
      }
    });

    // نشانگر طلایی متحرک Desktop: با Hover/Keyboard زیر همان لینک حرکت می‌کند
    // و پس از خروج، نرم به صفحه فعال برمی‌گردد.
    const navList = root.querySelector('.akx-nav > ul');
    if (navList) {
      const links = [...navList.querySelectorAll(':scope > li > a')];
      const activeLink = navList.querySelector(':scope > li.akx-active > a') || links[0];
      const moveIndicator = link => {
        if (!link) return;
        const listRect = navList.getBoundingClientRect();
        const linkRect = link.getBoundingClientRect();
        navList.style.setProperty('--akx-indicator-x', `${linkRect.left - listRect.left}px`);
        navList.style.setProperty('--akx-indicator-width', `${linkRect.width}px`);
        navList.classList.add('akx-indicator-ready');
      };
      links.forEach(link => {
        link.addEventListener('pointerenter', () => moveIndicator(link));
        link.addEventListener('focus', () => moveIndicator(link));
      });
      navList.addEventListener('pointerleave', () => moveIndicator(activeLink));
      navList.addEventListener('focusout', event => {
        if (!navList.contains(event.relatedTarget)) moveIndicator(activeLink);
      });
      requestAnimationFrame(() => moveIndicator(activeLink));
      window.addEventListener('resize', () => moveIndicator(activeLink), { passive: true });
    }

    // v3.10.68: نوار دوم چسبان — Mainbar وقتی جای طبیعی‌اش از بالا رد شد به بالای viewport می‌چسبد
    const mainbar = root.querySelector('.akx-mainbar');
    if (mainbar) {
      const spacer = document.createElement('div');
      spacer.className = 'akx-mainbar-spacer';
      mainbar.parentNode.insertBefore(spacer, mainbar.nextSibling);

      let threshold = 0;
      const isStuck = () => mainbar.classList.contains('is-stuck');

      function measure() {
        if (isStuck()) return; // موقع چسبیدن مختصات طبیعی معتبر نیست
        const rect = mainbar.getBoundingClientRect();
        threshold = rect.top + (window.scrollY || window.pageYOffset || 0);
      }

      function apply() {
        const y = window.scrollY || window.pageYOffset || 0;
        const shouldStick = threshold > 0 && y >= threshold;
        if (shouldStick === isStuck()) return;
        if (shouldStick) {
          spacer.style.height = mainbar.offsetHeight + 'px';
          mainbar.classList.add('is-stuck');
          root.classList.add('akx-has-stuck-bar');
        } else {
          mainbar.classList.remove('is-stuck');
          root.classList.remove('akx-has-stuck-bar');
          spacer.style.height = '0px';
        }
      }

      measure();
      apply();
      window.addEventListener('scroll', apply, { passive: true });
      window.addEventListener('resize', function () {
        if (isStuck()) {
          mainbar.classList.remove('is-stuck');
          root.classList.remove('akx-has-stuck-bar');
          spacer.style.height = '0px';
        }
        measure();
        apply();
      });
    }
  }

  function initAll() {
    document.querySelectorAll('#akx-header[data-akx-live="1"]').forEach(initRoot);
  }

  // v3.10.70: پاکسازی کپی Static قدیمی هدر که داخل HTML خود صفحه (Elementor HTML Widget)
  // با id تکراری akx-header و <style> اینلاین قدیمی (سقف 1380px و فونت‌های ریز) جاگذاری شده —
  // همان علت «تغییر نکردن ظاهر شورت‌کد». فقط هدر دارای data-akx-live معتبر نگه داشته می‌شود.
  function purgeStaticHeaderCopies() {
    const live = document.querySelector('#akx-header[data-akx-live="1"]');
    if (!live) return;
    document.querySelectorAll('#akx-header').forEach(function (node) {
      if (node !== live) node.remove();
    });
    document.querySelectorAll('style').forEach(function (tag) {
      if ((tag.textContent || '').indexOf('#akx-header') !== -1) tag.remove();
    });
  }

  // v3.10.69: حذف هدر تکراری خارجی (alookhor-categories-manager) و متن خام شورت‌کدهای
  // ثبت‌نشده — فقط وقتی هدر AKX خودمان روی صفحه رندر شده باشد (همان منطق تثبیت‌شده‌ی 3.10.57).
  function removeExternalDuplicate() {
    const ours = document.querySelector('#akx-header[data-akx-live="1"]');
    if (!ours) return;
    document.querySelectorAll('.alookhor-header-wrapper').forEach(function (wrapper) {
      if (!ours.contains(wrapper)) wrapper.remove();
    });
    purgeStaticHeaderCopies();
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    const nodes = [];
    while (walker.nextNode()) nodes.push(walker.currentNode);
    nodes.forEach(function (node) {
      const value = node.nodeValue || '';
      if (/\[\s*alookhor_[a-z0-9_]+\s*\]/i.test(value)) {
        node.nodeValue = value.replace(/\[\s*alookhor_[a-z0-9_]+\s*\]/gi, '').trim();
      }
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () { initAll(); removeExternalDuplicate(); }, { once: true });
  } else {
    initAll();
    removeExternalDuplicate();
  }

  // Watch for dynamically inserted headers
  try {
    var observer = new MutationObserver(function () {
      document.querySelectorAll('#akx-header[data-akx-live="1"]:not([data-akx-ready])').forEach(initRoot);
      removeExternalDuplicate();
    });
    observer.observe(document.documentElement, { childList: true, subtree: true });
  } catch (e) {
    /* MutationObserver unavailable */
  }
})();
